import java.util.*
import kotlin.math.*

data class Edge(val to: Int, var cap: Int, val rev: Int)

class Dinic(private val n: Int) {
    private val graph = Array(n) { mutableListOf<Edge>() }
    private var level = IntArray(n)
    private var it = IntArray(n)

    fun addEdge(from: Int, to: Int, cap: Int) {
        val fwd = Edge(to, cap, graph[to].size)
        val rev = Edge(from, 0, graph[from].size)
        graph[from].add(fwd)
        graph[to].add(rev)
    }

    private fun bfs(s: Int, t: Int): Boolean {
        java.util.Arrays.fill(level, -1)
        val q: Queue<Int> = ArrayDeque()
        level[s] = 0
        q.add(s)
        while (q.isNotEmpty()) {
            val v = q.poll()
            for (e in graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1
                    q.add(e.to)
                }
            }
        }
        return level[t] >= 0
    }

    private fun dfs(v: Int, t: Int, f: Int): Int {
        if (v == t) return f
        for (i in it[v] until graph[v].size) {
            it[v] = i
            val e = graph[v][i]
            if (e.cap > 0 && level[v] < level[e.to]) {
                val d = dfs(e.to, t, min(f, e.cap))
                if (d > 0) {
                    e.cap -= d
                    graph[e.to][e.rev].cap += d
                    return d
                }
            }
        }
        return 0
    }

    fun maxFlow(s: Int, t: Int): Int {
        var flow = 0
        val inf = Int.MAX_VALUE
        while (bfs(s, t)) {
            java.util.Arrays.fill(it, 0)
            var f: Int
            while (true) {
                f = dfs(s, t, inf)
                if (f == 0) break
                flow += f
            }
        }
        return flow
    }
}

fun main() {
    val br = System.`in`.bufferedReader()
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()
    val total = n * m

    val S = total * 2
    val T = S + 1
    val dinic = Dinic(T + 1)

    fun inId(i: Int, j: Int) = (i * m + j) * 2
    fun outId(i: Int, j: Int) = (i * m + j) * 2 + 1

    val dirs = arrayOf(intArrayOf(1,0), intArrayOf(-1,0), intArrayOf(0,1), intArrayOf(0,-1))

    for (i in 0 until n) {
        for (j in 0 until m) {
            val inNode = inId(i, j)
            val outNode = outId(i, j)
            // capacity 1 for each cell
            dinic.addEdge(inNode, outNode, 1)

            // stay edge from source to inNode
            dinic.addEdge(S, inNode, 1)

            // move edges from source to neighbors' inNodes
            for (d in dirs) {
                val ni = i + d[0]
                val nj = j + d[1]
                if (ni in 0 until n && nj in 0 until m) {
                    val neighIn = inId(ni, nj)
                    dinic.addEdge(S, neighIn, 1)
                }
            }

            // from outNode to sink
            dinic.addEdge(outNode, T, 1)
        }
    }

    val maxFlow = dinic.maxFlow(S, T)
    val answer = total - maxFlow
    println(answer)
}

