fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()
    val total = n * m

    // Precompute neighbors for each cell
    val neighbors = Array(total) { mutableListOf<Int>() }
    fun id(r: Int, c: Int) = r * m + c
    for (r in 0 until n) {
        for (c in 0 until m) {
            val v = id(r, c)
            if (r > 0) neighbors[v].add(id(r - 1, c))
            if (r < n - 1) neighbors[v].add(id(r + 1, c))
            if (c > 0) neighbors[v].add(id(r, c - 1))
            if (c < m - 1) neighbors[v].add(id(r, c + 1))
        }
    }

    // Precompute possible moves for each cell (stay + neighbors)
    val moves = Array(total) { IntArray(neighbors[it].size + 1) }
    for (v in 0 until total) {
        val list = IntArray(neighbors[v].size + 1)
        list[0] = v // stay
        for (i in neighbors[v].indices) {
            list[i + 1] = neighbors[v][i]
        }
        moves[v] = list
    }

    var best = 0

    fun dfs(v: Int, occ: IntArray) {
        if (v == total) {
            var free = 0
            for (x in 0 until total) if (occ[x] == 0) free++
            if (free > best) best = free
            return
        }
        val options = moves[v]
        for (t in options) {
            occ[t]++
            dfs(v + 1, occ)
            occ[t]--
        }
    }

    val occ = IntArray(total)
    dfs(0, occ)
    println(best)
}

