fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()
    val total = n * m

    // Precompute neighbors for each cell
    val neighbors = Array(total) { mutableListOf<Int>() }
    fun idx(r: Int, c: Int) = r * m + c

    for (r in 0 until n) {
        for (c in 0 until m) {
            val v = idx(r, c)
            if (r > 0) neighbors[v].add(idx(r - 1, c))
            if (r < n - 1) neighbors[v].add(idx(r + 1, c))
            if (c > 0) neighbors[v].add(idx(r, c - 1))
            if (c < m - 1) neighbors[v].add(idx(r, c + 1))
        }
    }

    val size = 1 shl total
    val reachable = BooleanArray(size)

    // For each spider (cell), compute its possible destination mask
    val destMasks = IntArray(total)
    for (v in 0 until total) {
        var mask = 1 shl v // staying
        for (u in neighbors[v]) {
            mask = mask or (1 shl u)
        }
        destMasks[v] = mask
    }

    // Enumerate all combinations of choices for each spider
    // Using DFS over cells, building destination mask
    fun dfs(pos: Int, curMask: Int) {
        if (pos == total) {
            reachable[curMask] = true
            return
        }
        var options = destMasks[pos]
        while (options != 0) {
            val lsb = options and -options
            val nextMask = curMask or lsb
            dfs(pos + 1, nextMask)
            options -= lsb
        }
    }

    dfs(0, 0)

    var best = 0
    for (mask in 0 until size) {
        if (reachable[mask]) {
            val occupied = Integer.bitCount(mask)
            val empty = total - occupied
            if (empty > best) best = empty
        }
    }

    println(best)
}

