            if (c > 0) neighbors[v].add(id(r, c - 1))
            if (c + 1 < m) neighbors[v].add(id(r, c + 1))
        }
    }

    val maxMask = 1 shl total
    var best = 0

    // For each subset of cells as final occupied cells
    for (mask in 0 until maxMask) {
        val occupiedCount = Integer.bitCount(mask)
        if (occupiedCount == 0) continue
        if (occupiedCount <= best) continue  // cannot improve

        // For each cell, check if it has at least one possible incoming spider
        var possible = true
        var v = 0
        while (v < total && possible) {
            if ((mask and (1 shl v)) != 0) {
                var hasIncoming = false
                // from itself
                if (true) {
                    hasIncoming = true
                }
                // from neighbors (not necessary since self always possible)
                // but we keep structure for clarity
                if (!hasIncoming) {
                    for (u in neighbors[v]) {
                        hasIncoming = true
                        break
                    }
                }
                if (!hasIncoming) possible = false
            }
            v++
        }
        if (!possible) continue

        // Always possible because each spider can stay in its own cell,
        // and multiple spiders can share cells.
        if (occupiedCount > best) best = occupiedCount
    }

    val answer = total - best
    println(answer)
}

