data class Edge(val to: Int, var cap: Int, val rev: Int)

class MaxFlow(private val n: Int) {
    private val graph = Array(n) { mutableListOf<Edge>() }

    fun addEdge(from: Int, to: Int, cap: Int) {
        val fwd = Edge(to, cap, graph[to].size)
        val rev = Edge(from, 0, graph[from].size)
        graph[from].add(fwd)
        graph[to].add(rev)
    }

    fun maxFlow(s: Int, t: Int): Int {
        var flow = 0
        val level = IntArray(n)
        val it = IntArray(n)

        fun bfs(): Boolean {
            Arrays.fill(level, -1)
            val q: Queue<Int> = ArrayDeque()
            level[s] = 0
            q.add(s)
            while (q.isNotEmpty()) {
                val v = q.poll()
                for (e in graph[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1
                        q.add(e.to)
                    }
                }
            }
            return level[t] >= 0
        }

        fun dfs(v: Int, upTo: Int): Int {
            if (v == t) return upTo
            var i = it[v]
            while (i < graph[v].size) {
                val e = graph[v][i]
                if (e.cap > 0 && level[v] < level[e.to]) {
                    val d = dfs(e.to, min(upTo, e.cap))
                    if (d > 0) {
                        e.cap -= d
                        graph[e.to][e.rev].cap += d
                        return d
                    }
                }
                it[v] = ++i
            }
            return 0
        }

        while (bfs()) {
            Arrays.fill(it, 0)
            var f: Int
            while (true) {
                f = dfs(s, Int.MAX_VALUE)
                if (f == 0) break
                flow += f
            }
        }
        return flow
    }
}

