fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()
    val total = n * m

    val cells = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until n) {
        for (j in 0 until m) {
            cells.add(Pair(i, j))
        }
    }

    val neighbors = Array(total) { mutableListOf<Int>() }
    for (idx in 0 until total) {
        val (i, j) = cells[idx]
        neighbors[idx].add(idx) // stay
        if (i > 0) neighbors[idx].add((i - 1) * m + j)
        if (i + 1 < n) neighbors[idx].add((i + 1) * m + j)
        if (j > 0) neighbors[idx].add(i * m + (j - 1))
        if (j + 1 < m) neighbors[idx].add(i * m + (j + 1))
    }

    val maxMask = 1 shl total
    var best = 0

    for (mask in 0 until maxMask) {
        var possible = true
        for (s in 0 until total) {
            if (((mask shr s) and 1) == 0) continue
            var can = false
            for (t in neighbors[s]) {
                if (((mask shr t) and 1) == 1) {
                    can = true
                    break
                }
            }
            if (!can) {
                possible = false
                break
            }
        }
        if (!possible) continue

        val indeg = IntArray(total)
        for (s in 0 until total) {
            if (((mask shr s) and 1) == 0) continue
            for (t in neighbors[s]) {
                if (((mask shr t) and 1) == 1) {
                    indeg[t]++
                }
            }
        }

        var sum = 0
        for (t in 0 until total) {
            if (((mask shr t) and 1) == 0) continue
            if (indeg[t] == 0) {
                sum = -1
                break
            }
            sum += indeg[t]
        }
        if (sum == -1) continue
        if (sum >= total) {
            val count = Integer.bitCount(mask)
            val empty = total - count
            if (empty > best) best = empty
        }
    }

    println(best)
}

