fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()
    val total = n * m

    // Precompute neighbors for each cell
    val neighbors = Array(total) { mutableListOf<Int>() }
    fun id(r: Int, c: Int) = r * m + c
    val dr = intArrayOf(-1, 1, 0, 0)
    val dc = intArrayOf(0, 0, -1, 1)

    for (r in 0 until n) {
        for (c in 0 until m) {
            val v = id(r, c)
            for (k in 0 until 4) {
                val nr = r + dr[k]
                val nc = c + dc[k]
                if (nr in 0 until n && nc in 0 until m) {
                    neighbors[v].add(id(nr, nc))
                }
            }
        }
    }

    // Precompute possible moves for each spider (including staying)
    val moves = Array(total) { IntArray(neighbors[it].size + 1) }
    for (v in 0 until total) {
        val list = neighbors[v]
        val arr = IntArray(list.size + 1)
        arr[0] = v // stay
        for (i in list.indices) arr[i + 1] = list[i]
        moves[v] = arr
    }

    var best = 0
    val positions = IntArray(total)

    fun dfs(spider: Int) {
        if (spider == total) {
            val occupied = BooleanArray(total)
            for (i in 0 until total) occupied[positions[i]] = true
            var cnt = 0
            for (i in 0 until total) if (!occupied[i]) cnt++
            if (cnt > best) best = cnt
            return
        }
        for (dest in moves[spider]) {
            positions[spider] = dest
            dfs(spider + 1)
        }
    }

    dfs(0)
    println(best)
}
